import{_ as a,k as i,q as t,au as r}from"./chunks/framework.BaJNrnLw.js";const u=JSON.parse('{"title":"What is Protocol Launcher?","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/what-is-it.md","filePath":"en/guide/what-is-it.md"}'),l={name:"guide/what-is-it.md"};function o(s,e,p,n,h,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocol-launcher/guide/what-is-it.md for this page in Markdown format</div><h1 id="what-is-protocol-launcher" tabindex="-1">What is Protocol Launcher? <a class="header-anchor" href="#what-is-protocol-launcher" aria-label="Permalink to “What is Protocol Launcher?”">​</a></h1><p><strong>Protocol Launcher</strong> is a TypeScript library designed to generate &quot;Quick Launch&quot; URLs (Deep Links) for various applications.</p><p>These URLs allow users to trigger specific actions in applications with a single click, such as installing plugins, configuring servers, or setting up API keys.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to “Key Features”">​</a></h2><ul><li><strong>Type-Safe</strong>: Strict TypeScript types validate payloads and prevent malformed links.</li><li><strong>Multi-App Ready</strong>: Extensible design to support many apps via URL schemes.</li><li><strong>On-Demand / Tree-shakable</strong>: Import only what you need; small bundle footprint.</li><li><strong>Secure Encoding</strong>: Encodes configs safely to avoid injection. Supports Unicode characters including Chinese.</li><li><strong>Zero Runtime Dependencies</strong>: Lightweight library with no external runtime dependencies.</li><li><strong>ESM First</strong>: Modern ES Modules, works in Node and bundlers.</li></ul><h2 id="supported-applications" tabindex="-1">Supported Applications <a class="header-anchor" href="#supported-applications" aria-label="Permalink to “Supported Applications”">​</a></h2><p>Currently, we support the following applications:</p><ul><li><a href="./../apps/bbedit.html">BBEdit</a></li><li><a href="./../apps/cherry-studio.html">Cherry Studio</a></li><li><a href="./../apps/code-buddy.html">CodeBuddy</a></li><li><a href="./../apps/codelite.html">CodeLite</a></li><li><a href="./../apps/cursor.html">Cursor</a></li><li><a href="./../apps/github-desktop.html">GitHub Desktop</a></li><li><a href="./../apps/goland.html">GoLand</a></li><li><a href="./../apps/idea.html">IntelliJ IDEA</a></li><li><a href="./../apps/kiro.html">Kiro</a></li><li><a href="./../apps/lingma.html">Lingma</a></li><li><a href="./../apps/macvim.html">MacVim</a></li><li><a href="./../apps/opencode.html">OpenCode</a></li><li><a href="./../apps/pearai.html">PearAI</a></li><li><a href="./../apps/phpstorm.html">PhpStorm</a></li><li><a href="./../apps/pycharm.html">PyCharm</a></li><li><a href="./../apps/qoder.html">Qoder</a></li><li><a href="./../apps/rustrover.html">RustRover</a></li><li><a href="./../apps/telegram.html">Telegram</a></li><li><a href="./../apps/textmate.html">TextMate</a></li><li><a href="./../apps/thunder.html">Thunder</a></li><li><a href="./../apps/vscode.html">VS Code</a></li><li><a href="./../apps/webstorm.html">WebStorm</a></li><li><a href="./../apps/xcode.html">Xcode</a></li><li><a href="./../apps/zed.html">Zed</a></li></ul><p>More applications will be added in the future.</p>',10)])])}const m=a(l,[["render",o]]);export{u as __pageData,m as default};
